using System;
using System.IO;
using System.Linq;
using CrossVault.FoxDbf.Sql;
using Xunit;

namespace CrossVault.FoxDbf.Tests;

/// <summary>
/// Field names with non-ASCII letters, read from VFP9-generated fixtures (<c>vfp_test/uninames/</c>,
/// regenerated by <c>mkuninames.prg</c>, CP1252). VFP9 accepts <c>razónSoc</c> as a free-table field
/// name and <c>razónSocial</c> as a DBC long name, both in expressions and qualified in SQL.
/// <para>
/// Two layers have to agree: the expression lexer must accept the letters, and the header reader must
/// decode the 10-character descriptor name in the table's code page (0xD3 = 'Ó') rather than as ASCII
/// — otherwise the column is named <c>RAZ?NSOC</c> and a query silently reads <c>null</c> for it.
/// </para>
/// </summary>
public sealed class UnicodeFieldNameFixtureTests : IDisposable
{
    private readonly SqlTestSupport.TempDir _dir = new();

    public UnicodeFieldNameFixtureTests()
    {
        foreach (var file in Directory.GetFiles(Fixtures.VfpTest("uninames")))
            if (!file.EndsWith(".prg", StringComparison.OrdinalIgnoreCase))
                File.Copy(file, Path.Combine(_dir.Path, Path.GetFileName(file)));
    }

    public void Dispose() => _dir.Dispose();

    private static object?[][] Rows(VfpSession s, string sql) => s.Execute(sql)!.Rows.Select(r => r.ToArray()).ToArray();

    [Fact]
    public void FreeTable_HeaderName_IsDecodedInTheTableCodePage()
    {
        using var table = DbfTable.Open(Path.Combine(_dir.Path, "unifree.dbf"));
        Assert.Equal("RAZÓNSOC", table.Columns[0].Name);
    }

    [Fact]
    public void FreeTable_QualifiedUnicodeProjection_ReadsTheFilteredRow()
    {
        using var s = new VfpSession();
        s.OpenDirectory(_dir.Path);

        var rows = Rows(s, "SELECT f.razónSoc FROM unifree f WHERE razónSoc = 'ACME'");
        Assert.Single(rows);
        Assert.Equal("ACME", ((string)rows[0][0]!).TrimEnd());
    }

    [Fact]
    public void FreeTable_BareUnicodeField_ReadsEveryValue()
    {
        using var s = new VfpSession();
        s.OpenDirectory(_dir.Path);

        var values = Rows(s, "SELECT razónSoc FROM unifree ORDER BY id").Select(r => ((string)r[0]!).TrimEnd());
        Assert.Equal(new[] { "ACME", "Peñarol" }, values);
    }

    [Fact]
    public void DbcTable_UnicodeLongNames_Read()
    {
        using var s = new VfpSession();
        s.OpenDatabase(Path.Combine(_dir.Path, "uninames.DBC"));

        var rows = Rows(s, "SELECT c.razónSocial, c.información FROM clientes c ORDER BY c.id");
        Assert.Equal(2, rows.Length);
        Assert.Equal("ACME S.A.", ((string)rows[0][0]!).TrimEnd());
        Assert.Equal("dos", ((string)rows[1][1]!).TrimEnd());
    }

    [Fact]
    public void DbcTable_UnicodeLongName_IsPushedBelowAJoin()
    {
        using var s = new VfpSession();
        s.OpenDatabase(Path.Combine(_dir.Path, "uninames.DBC"));
        const string sql = "SELECT a.razónSocial, b.información FROM clientes a INNER JOIN clientes b ON a.id = b.id " +
                           "WHERE a.razónSocial = 'Peñarol S.A.'";

        var ex = new SelectExecutor(s);
        var rows = ex.Run((SelectStatement)SqlParser.Parse(sql)).Rows.Select(r => r.ToArray()).ToArray();

        Assert.Equal(new[] { "a.razónSocial = 'Peñarol S.A.'" }, ex.PushdownFilters);
        Assert.Single(rows);
        Assert.Equal("dos", ((string)rows[0][1]!).TrimEnd());
    }
}
